import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { spawnSync } from "node:child_process";

const read = (relative) => readFile(new URL(`../${relative}`, import.meta.url), "utf8");
const [pkgSource, lockSource, generator, bundle, spaContract] = await Promise.all([
  read("package.json"),
  read("package-lock.json"),
  read("scripts/build-shell-bundle.mjs"),
  read("root-site/shell/shell.bundle.js"),
  read("scripts/test-spa-p1.mjs")
]);
const pkg = JSON.parse(pkgSource);
const lock = JSON.parse(lockSource);

assert.equal(pkg.devDependencies.esbuild, "0.21.5",
  "esbuild must be pinned exactly so another machine emits the same shell bytes");
assert.equal(lock.packages[""].devDependencies.esbuild, "0.21.5",
  "the lockfile root must pin the same direct esbuild version");
assert.equal(pkg.scripts["build:shell"], "node scripts/build-shell-bundle.mjs");
assert.equal(pkg.scripts["check:shell"], "node scripts/build-shell-bundle.mjs --check");
assert.match(pkg.scripts.build, /npm run build:shell && node scripts\/build-front-door\.mjs/,
  "the production build must regenerate the shell before copying root-site");

assert.match(generator, /entryPoints:\s*\["root-site\/shell\/shell\.js"\]/);
assert.match(generator, /bundle:\s*true/);
assert.match(generator, /format:\s*"iife"/);
assert.match(generator, /charset:\s*"ascii"/);
assert.match(generator, /write:\s*false/);
assert.match(generator, /current\.equals\(Buffer\.from\(output\.contents\)\)/,
  "check mode must compare exact bytes, not only menu text or hashes maintained by hand");
assert.ok(bundle.startsWith("// GENERATED by scripts/build-shell-bundle.mjs"),
  "the committed bundle must tell maintainers not to edit it");

const check = spawnSync(process.execPath, ["scripts/build-shell-bundle.mjs", "--check"], {
  cwd: new URL("..", import.meta.url),
  encoding: "utf8"
});
assert.equal(check.status, 0, `${check.stdout}\n${check.stderr}`.trim());
assert.match(check.stdout, /shell\.bundle\.js matches shell\.js/);

assert.match(spaContract, /assert\.deepEqual\(componentMenuIds, routeMenuIds,/,
  "phase one must retain the controller-vs-route menu sequence lock");
assert.match(spaContract, /assert\.deepEqual\(bundleMenuIds, routeMenuIds,/,
  "phase one must retain the bundle-vs-route menu sequence lock beside byte parity");
assert.match(spaContract, /all three Bizflow menu copies must retain the approved item order/,
  "the old approved-order lock stays until the phase-two registry replaces it");

console.log("MENU-unify-1 batch 1 contracts: PASS (pinned builder, generated bundle, byte parity, legacy lock retained)");
